<script setup lang="ts">
import {onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{Plus,Refresh,Search}from'@element-plus/icons-vue';import type{components}from'@ism/api-client';import{useSessionStore}from'../stores/session';type Issue=components['schemas']['SafetyIssue'];type Project=components['schemas']['ProjectSummary'];const session=useSessionStore(),loading=ref(false),dialog=ref(false),issues=ref<Issue[]>([]),projects=ref<Project[]>([]),total=ref(0);const q=reactive({keyword:'',status:'',page:0,size:20});const form=reactive({issueNo:'',title:'',projectId:'',category:'BEHAVIOR' as components['schemas']['SafetyIssueCategory'],severity:'MEDIUM' as components['schemas']['SafetyIssueSeverity'],description:'',location:'',discoveredAt:'',deadline:'',responsibleUserId:''});const statuses={OPEN:'待整改',PENDING_REVIEW:'待验收',CLOSED:'已关闭'},severities={LOW:'低',MEDIUM:'中',HIGH:'高',CRITICAL:'重大'};
async function load(){loading.value=true;const{data}=await session.client.GET('/safety/issues',{params:{query:{keyword:q.keyword||undefined,status:(q.status||undefined)as components['schemas']['SafetyIssueStatus']|undefined,page:q.page,size:q.size}}});issues.value=data?.data?.items??[];total.value=data?.data?.total??0;loading.value=false;}async function open(){const{data}=await session.client.GET('/projects',{params:{query:{status:'ACTIVE',page:0,size:100}}});projects.value=data?.data?.items??[];Object.assign(form,{issueNo:'',title:'',projectId:'',category:'BEHAVIOR',severity:'MEDIUM',description:'',location:'',discoveredAt:'',deadline:'',responsibleUserId:session.actorId??''});dialog.value=true;}async function save(){if(!form.issueNo||!form.title||!form.projectId||!form.description||!form.discoveredAt||!form.deadline){ElMessage.warning('请完整填写必填项');return;}const{error}=await session.client.POST('/safety/issues',{body:{...form,location:form.location||undefined,version:0}});if(error)ElMessage.error(error.error.message);else{dialog.value=false;await load();}}async function rectify(row:Issue){const note=(await ElMessageBox.prompt('请输入整改说明','提交整改',{inputPattern:/.+/})).value;const fileId=(await ElMessageBox.prompt('请输入整改附件文件 ID','整改证据',{inputPattern:/^[1-9][0-9]*$/})).value;const{error}=await session.client.POST('/safety/issues/{id}/rectification',{params:{path:{id:row.id}},body:{note,fileId,version:row.version}});if(error)ElMessage.error(error.error.message);else await load();}async function verify(row:Issue,decision:'PASS'|'REJECT'){const comment=(await ElMessageBox.prompt('请输入验收意见',decision==='PASS'?'验收通过':'驳回整改',{inputPattern:/.+/})).value;const{error}=await session.client.POST('/safety/issues/{id}/verification',{params:{path:{id:row.id}},body:{decision,comment,version:row.version}});if(error)ElMessage.error(error.error.message);else await load();}onMounted(load);
</script>
<template><div class="page"><div class="page-heading"><div><h1>安全隐患整改</h1><p>登记、整改、复查和关闭工业现场安全隐患</p></div><el-button type="primary" :icon="Plus" @click="open">登记隐患</el-button></div><el-card shadow="never" class="filter-card"><el-form inline><el-form-item label="关键词"><el-input v-model="q.keyword" :prefix-icon="Search" clearable/></el-form-item><el-form-item label="状态"><el-select v-model="q.status" clearable style="width:150px"><el-option v-for="(value,key) in statuses" :key="key" :label="value" :value="key"/></el-select></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button :icon="Refresh" @click="q.keyword='';q.status='';load()">重置</el-button></el-form></el-card><el-card shadow="never" class="table-card"><el-table v-loading="loading" :data="issues"><el-table-column prop="issueNo" label="隐患编号" width="140"/><el-table-column label="隐患/项目" min-width="250"><template #default="{row}"><strong>{{row.title}}</strong><div class="subtext">{{row.projectName}} · {{row.supplierName}}</div></template></el-table-column><el-table-column label="等级" width="90"><template #default="{row}">{{severities[row.severity as keyof typeof severities]}}</template></el-table-column><el-table-column prop="deadline" label="整改期限" width="120"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.overdue?'danger':''">{{row.overdue?'已逾期':statuses[row.status as keyof typeof statuses]}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button v-if="row.status==='OPEN'" link type="primary" @click="rectify(row)">提交整改</el-button><template v-if="row.status==='PENDING_REVIEW'"><el-button link type="success" @click="verify(row,'PASS')">通过</el-button><el-button link type="danger" @click="verify(row,'REJECT')">驳回</el-button></template></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="登记安全隐患" width="720px"><el-form label-position="top"><el-row :gutter="18"><el-col :span="12"><el-form-item label="隐患编号 *"><el-input v-model="form.issueNo"/></el-form-item></el-col><el-col :span="12"><el-form-item label="隐患标题 *"><el-input v-model="form.title"/></el-form-item></el-col><el-col :span="12"><el-form-item label="所属项目 *"><el-select v-model="form.projectId" style="width:100%"><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id"/></el-select></el-form-item></el-col><el-col :span="6"><el-form-item label="类别"><el-select v-model="form.category"><el-option label="人员行为" value="BEHAVIOR"/><el-option label="设备设施" value="EQUIPMENT"/><el-option label="环境" value="ENVIRONMENT"/><el-option label="管理" value="MANAGEMENT"/></el-select></el-form-item></el-col><el-col :span="6"><el-form-item label="等级"><el-select v-model="form.severity"><el-option v-for="(value,key) in severities" :key="key" :label="value" :value="key"/></el-select></el-form-item></el-col><el-col :span="24"><el-form-item label="隐患描述 *"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item></el-col><el-col :span="12"><el-form-item label="发现时间 *"><el-date-picker v-model="form.discoveredAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></el-col><el-col :span="12"><el-form-item label="整改期限 *"><el-date-picker v-model="form.deadline" value-format="YYYY-MM-DD"/></el-form-item></el-col></el-row></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">登记</el-button></template></el-dialog><div class="pagination">共 {{total}} 条</div></div></template>
